var e=new class{archiveBaseUrl=`/events-archive`;async createArchiveFile(e){return{success:!1,fileName:``,error:`La migración se gestiona automáticamente vía GitHub Actions cada 1 de enero.`}}async archiveExists(e){try{let t=await fetch(`${this.archiveBaseUrl}/${e}.json`);if(!t.ok)return!1;let n=t.headers.get(`content-type`);return!(n&&n.includes(`text/html`))}catch{return!1}}async getArchiveData(e){try{console.log(`[StaticFileService] Cargando datos de ${e}...`);let t=await fetch(`${this.archiveBaseUrl}/${e}.json`);if(!t.ok)return console.warn(`[StaticFileService] No se encontró el archivo de ${e}`),null;let n=t.headers.get(`content-type`);if(n&&n.includes(`text/html`))return console.warn(`[StaticFileService] El archivo de ${e} devolvió HTML (404 reescrito)`),null;let r=await t.json();return console.log(`[StaticFileService] ✅ ${e} cargado con ${r.events?.length||0} eventos.`),r}catch(t){return console.error(`[StaticFileService] Error al cargar ${e}:`,t),null}}async getAvailableYears(){try{let e=await fetch(`${this.archiveBaseUrl}/index.json`);if(e.ok){let t=e.headers.get(`content-type`);if(t&&!t.includes(`text/html`)){let t=await e.json();return console.log(`[StaticFileService] Índice cargado:`,t.years),t.years||[]}}console.log(`[StaticFileService] Índice no encontrado o inválido, buscando manualmente...`);let t=new Date().getFullYear(),n=[];for(let e=2024;e<t;e++)await this.archiveExists(e)&&n.push(e);return console.log(`[StaticFileService] Años encontrados manualmente:`,n),n.sort((e,t)=>t-e)}catch(e){return console.error(`[StaticFileService] Error al obtener años:`,e),[]}}};export{e as staticFileService};